// Group billable items by client
const items = $input.all().map(item => item.json);

const clients = {};

items.forEach(item => {
  if (item.status !== 'billable') return;

  const clientId = item.client_id || item.client;
  if (!clients[clientId]) {
    clients[clientId] = {
      client_id: clientId,
      client_name: item.client_name || item.client,
      client_email: item.client_email || '',
      client_address: item.client_address || '',
      tax_code: item.tax_code || '',
      items: [],
      subtotal: 0,
      tax_rate: item.tax_rate || 0.10, // 10% VAT default
      total: 0
    };
  }

  clients[clientId].items.push({
    service: item.service || item.description,
    quantity: parseInt(item.quantity) || 1,
    rate: parseFloat(item.rate) || 0,
    amount: parseFloat(item.amount) || 0
  });

  clients[clientId].subtotal += parseFloat(item.amount) || 0;
});

// Calculate totals
Object.values(clients).forEach(client => {
  client.tax_amount = client.subtotal * client.tax_rate;
  client.total = client.subtotal + client.tax_amount;
  client.invoice_number = `INV-${Date.now()}-${client.client_id.substring(0, 3).toUpperCase()}`;
  client.invoice_date = new Date().toISOString().split('T')[0];
  client.due_date = new Date(Date.now() + 30*24*60*60*1000).toISOString().split('T')[0]; // 30 days
});

const clientList = Object.values(clients);
console.log(`Generated ${clientList.length} invoices`);

return clientList.map(client => ({ json: client }));

// Format invoice email tiếng Việt
const invoice = $input.first().json;

const lineItems = invoice.items.map((item, i) => {
  return `${i + 1}. ${item.service}\n   Số lượng: ${item.quantity} x Đơn giá: ${item.rate.toLocaleString('vi-VN')}đ = ${item.amount.toLocaleString('vi-VN')}đ`;
}).join('\n\n');

const email = {
  to: invoice.client_email,
  subject: `Hóa đơn #${invoice.invoice_number} - ${invoice.invoice_date}`,
  body: `Kính gửi ${invoice.client_name},\n\nCảm ơn quý khách đã sử dụng dịch vụ của chúng tôi!\n\n━━━━━━━━━━━━━━━━━━━━
📄 HÓA ĐƠN
━━━━━━━━━━━━━━━━━━━━

Mã hóa đơn: #${invoice.invoice_number}
Ngày: ${invoice.invoice_date}
Hạn thanh toán: ${invoice.due_date}

━━━━━━━━━━━━━━━━━━━━
📋 CHI TIẾT DỊCH VỤ
━━━━━━━━━━━━━━━━━━━━

${lineItems}

━━━━━━━━━━━━━━━━━━━━
💰 THANH TOÁN
━━━━━━━━━━━━━━━━━━━━

Tạm tính: ${invoice.subtotal.toLocaleString('vi-VN')}đ
Thuế VAT (10%): ${invoice.tax_amount.toLocaleString('vi-VN')}đ

💵 TỔNG CỘNG: ${invoice.total.toLocaleString('vi-VN')}đ

━━━━━━━━━━━━━━━━━━━━
🏦 THÔNG TIN THANH TOÁN
━━━━━━━━━━━━━━━━━━━━

Ngân hàng: [Tên ngân hàng]
Số tài khoản: [Số tài khoản]
Chủ tài khoản: [Tên công ty]
Nội dung chuyển khoản: ${invoice.invoice_number}

━━━━━━━━━━━━━━━━━━━━

Quý khách vui lòng thanh toán trước hạn thanh toán.
Nếu có thắc mắc, vui lòng liên hệ kế toán.

Trân trọng,
Phòng Kế toán`,
  invoice_data: invoice
};

return [{ json: email }];

